// Упражнения в тетрадь главы «Произношение». n — постоянный номер: не менять и не переиспользовать.
// Только слова с одной нормой произношения; варианты нормы — в «Тонкостях» теории и в заданиях ★★★★★ с пометкой «Тонкость».
// Намеренно неверная транскрипция (найти ошибку) встречается только в заданиях «найти и исправить».
const PZ_CLASSIC=[
// ── Урок 1. Орфоэпия. Произносительная норма
 {n:1,l:1,st:1,task:`Прочитать пары слов. Выписать в первый столбик литературные варианты, во второй — просторечные (искажённые). Подчеркнуть букву, которой обозначен звук, различающий слова пары.`,
  obr:`Коридор — колидор: в просторечном варианте [л] вместо [р].`,
  body:`Колидор — коридор; трамвай — транвай; будущий — будующий; директор — дилектор; тубаретка — табуретка; пинжак — пиджак; серьёзный — сурьёзный; ндравится — нравится; секретарь — секлетарь; радиво — радио; поликлиника — полуклиника; скрыпка — скрипка; инцидент — инциндент; мармелад — мармалад.`,
  key:'Литературные: коридор, трамвай, будущий, директор, табуретка, пиджак, серьёзный, нравится, секретарь, радио, поликлиника, скрипка, инцидент, мармелад.<br>Просторечные: колидор (л вместо р), транвай (н вместо м), будующий (лишний у), дилектор (л вместо р), тубаретка (у вместо а), пинжак (н вместо д), сурьёзный (у вместо е), ндравится (лишний д), секлетарь (л вместо р), радиво (лишний в), полуклиника (у вместо и), скрыпка (ы вместо и), инциндент (лишний н), мармалад (а вместо е).'},
 {n:2,l:1,st:2,task:`Прочитать слова и их транскрипцию. Найти места, где произношение расходится с написанием, и назвать, что происходит: гласный без ударения, оглушение, озвончение, непроизносимый согласный. Где расхождений два, назвать оба.`,
  obr:`Город [го́рат]: о во втором слоге без ударения звучит как [а]; д на конце оглушается — [т].`,
  body:`Рыбка [ры́пка]; сугроб [сугро́п]; сделка [зд'э́лка]; окошко [ако́шка]; лошадь [ло́шат']; повязка [пав'а́ска]; отдых [о́ддых]; ловкий [ло́фк'ий']; кружка [кру́шка]; сторож [сто́раш]; местный [м'э́сный']; подход [патхо́т].`,
  key:'Рыбка — б перед глухим оглушается: [п]. Сугроб — б на конце: [п]. Сделка — с перед звонким озвончается: [з]. Окошко — оба безударных о: [а]. Лошадь — о без ударения: [а]; д\' на конце: [т\']. Повязка — о без ударения: [а]; з перед глухим: [с]. Отдых — т перед звонким: [д]. Ловкий — в перед глухим: [ф]. Кружка — ж перед глухим: [ш]. Сторож — о без ударения: [а]; ж на конце: [ш]. Местный — т не произносится. Подход — о без ударения: [а]; д перед глухим: [т]; д на конце: [т].'},
 {n:3,l:1,st:2,task:`Прочитать статьи из орфоэпического словаря. Объяснить, что показывает помета в скобках, и произнести каждое слово вслух. Подчеркнуть слова с ударением на последнем слоге.`,
  obr:`Ле́стный [сн] — на месте стн звучит [сн]: т не произносится.`,
  body:`Скворе́чник [шн]; ле́стный [сн]; изве́стный [сн]; шимпанзе́ [зэ]; кабаре́ [рэ]; корте́ж [тэ]; брошю́ра [шу]; прое́кт [эк]; скоростно́й [сн]; добросо́вестный [сн]; ателье́ [тэ]; у́стный [сн].`,
  key:'[шн] — на месте чн звучит [шн] (скворечник). [сн] — на месте стн звучит [сн], т не произносится (лестный, известный, скоростной, добросовестный, устный). [зэ], [рэ], [тэ] — согласный перед е твёрдый (шимпанзе, кабаре, кортеж, ателье). [шу] — ш твёрдый, на месте ю звучит [у] (брошюра). [эк] — после о звучит [э] без [й\'] (проект).<br>Ударение на последнем слоге: шимпанзе́, кабаре́, корте́ж, скоростно́й, ателье́.'},
 {n:4,l:1,st:2,task:`1) Записать полностью слова, которые в беглой речи произносятся сокращённо. 2) Указать, в каких ситуациях такое произношение недопустимо, и объяснить почему.`,
  obr:`«Щас» — сейчас.`,
  body:`Слова: «щас», «здрасте», «скока», «тыща», «грит», «када», «седня», «ваще», «чё», «пасиб», «пжалста», «токо».<br>Ситуации:<br>А) ответ на экзамене;<br>Б) разговор с другом в автобусе;<br>В) объявление по школьному радио;<br>Г) чтение стихотворения на конкурсе.`,
  key:'1) Сейчас, здравствуйте, сколько, тысяча, говорит, когда, сегодня, вообще, что, спасибо, пожалуйста, только.<br>2) Недопустимо в ситуациях А, В, Г: там нужен полный стиль — чёткое произношение по норме. В ситуации Б беглая речь естественна, хотя и в ней лучше не злоупотреблять сокращениями.'},
 {n:5,l:1,st:3,task:`Прочитать отрывок вслух. 1) Записать транскрипцию слов «опора», «один», «могучий», «язык», «свободный». 2) Объяснить, почему в этих словах произношение расходится с написанием. 3) Найти ещё три слова отрывка, в которых безударный гласный звучит не так, как пишется.`,
  obr:`Опора [апо́ра]: первая о без ударения звучит как [а].`,
  body:`Во дни сомнений, во дни тягостных раздумий о судьбах моей родины, — ты один мне поддержка и опора, о великий, могучий, правдивый и свободный русский язык! (И. С. Тургенев, «Русский язык»)`,
  key:'1) [апо́ра], [ад\'и́н], [магу́ч\'ий\'], [й\'изы́к], [свабо́дный\'].<br>2) О без ударения звучит как [а]; я в начале слова без ударения — два звука [й\'и].<br>3) Например: сомнений (о — [а]), моей (о — [а]), поддержка (о — [а]), великий (е — [и]); в слове «тягостных» о без ударения — [а], а т не произносится.'},
 {n:6,l:1,st:3,task:`Прочитать предложения. Найти просторечные слова и формы, заменить их литературными. Объяснить, зачем писатели вводят такие слова в текст. Затем заменить литературными просторечные слова из списка.`,
  obr:`Завсегда — всегда.`,
  body:`Предложения:<br>1. Я хоть грамоте знаю и читать завсегда охоча была, но что читать? (И. С. Тургенев, «Записки охотника»)<br>2. Да разве братец ихний приехали? (А. П. Чехов, «Хамелеон»)<br>3. Я завсегда вам, как благодетелю моему, благодарна. (В. Я. Брюсов, «Обручение Даши»)<br>Слова: вчерась, тута, нонче, кажный, евоный, ихний, ейный.`,
  key:'Предложения: 1, 3 — завсегда (литературно: всегда); 2 — ихний (литературно: их); приехали — об одном человеке (литературно: приехал). Писатели так показывают героя: кто он, откуда, как говорит; это речевая характеристика, а не ошибка автора.<br>Слова: вчера, тут, нынче (сейчас), каждый, его, их, её.'},
 {n:7,l:1,st:2,task:`Определить, сколько в каждом слове букв и сколько звуков. Объяснить, почему их число не совпадает. Слова, в которых букв и звуков поровну, выписать отдельно.`,
  obr:`Ёжик — 4 буквы, 5 звуков [й'о́жык]: ё в начале слова обозначает два звука.`,
  body:`Яблоко, съезд, вьюга, пень, стулья, июль, семья, грустный, лестница, моряк, ель, якорь.`,
  key:'Яблоко — 6 букв, 7 звуков (я в начале — [й\'а]). Съезд — 5 букв, 5 звуков [сй\'э́ст]: ъ звука не обозначает, е — два звука. Вьюга — 5 букв, 5 звуков [в\'й\'у́га]. Пень — 4 буквы, 3 звука (ь не звук). Стулья — 6 букв, 6 звуков [сту́л\'й\'а]. Июль — 4 буквы, 4 звука [ий\'у́л\']. Семья — 5 букв, 5 звуков [с\'им\'й\'а́]. Грустный — 8 букв, 7 звуков (т не произносится). Лестница — 8 букв, 7 звуков (т не произносится). Моряк — 5 букв, 5 звуков [мар\'а́к]. Ель — 3 буквы, 3 звука [й\'э́л\']. Якорь — 5 букв, 5 звуков [й\'а́кар\'].<br>Поровну: съезд, вьюга, стулья, июль, семья, моряк, ель, якорь.'},
 {n:8,l:1,st:3,task:`Не заглядывая в словарь, записать, как, по своему мнению, произносится трудное место в каждом слове. Затем проверить себя по уроку или по орфоэпическому словарю и исправить ошибки. Подсчитать, сколько слов было произнесено верно.`,
  obr:`Звёздный — по-моему, д произносится; по уроку — не произносится: ошибка.`,
  body:`Что-нибудь, лестница, легко, детский, стенд, пастель, теория, катер, грустный, чтобы, почти, Фоминична.`,
  key:'Что-нибудь — [шт]; лестница — т не произносится: [л\'э́сн\'ица]; легко — [хк]: [л\'ихко́]; детский — тс звучит как [ц]: [д\'э́цк\'ий\']; стенд — т перед е твёрдый: с[тэ]нд; пастель — т перед е твёрдый: пас[тэ]ль; теория — т перед е мягкий; катер — т перед е мягкий: [ка́т\'ир]; грустный — т не произносится: [гру́сный\']; чтобы — [шт]: [што́бы]; почти — [ч\'т]: [пач\'т\'и́]; Фоминична — [шн]: отчество на -ична.'},
 {n:9,l:1,st:4,task:`Ведущий школьного радио так произнёс слова объявления (произношение — в скобках). Найти ошибки, определить вид каждой (по буквам, просторечная, местная) и записать правильное произношение. Верно произнесённые слова отметить.`,
  obr:``,
  body:`Слова:<br>А) что — [ч'то]<br>Б) тема — [т'э́ма]<br>В) честный — [ч'э́стный']<br>Г) коридор — «колидор»<br>Д) молодёжь — [молад'о́ш]<br>Е) пионер — [п'иан'э́р]<br>Ж) учиться — [уч'и́тс'а]<br>З) библиотека — «библивотека»<br>И) весёлый — [в'ас'о́лый']<br>К) мягко — [м'а́хка]`,
  key:'А) по буквам; верно [што]. Б) верно. В) по буквам; верно [ч\'э́сный\']. Г) просторечная; верно «коридор». Д) местная (оканье); верно [малад\'о́ш]. Е) верно. Ж) по буквам; верно [уч\'и́ца]. З) просторечная; верно «библиотека». И) местная (яканье); верно [в\'ис\'о́лый\']. К) верно.'},
 {n:10,l:1,st:5,os:'сочинение',task:`Написать сочинение-рассуждение (6–8 предложений) на тему «Зачем нужна единая норма произношения». Условия: 1) объяснить, что такое орфоэпическая норма; 2) привести не меньше трёх слов, которые часто произносят неправильно, и записать их правильное произношение; 3) назвать хотя бы один вид ошибок (по буквам, просторечные, местные); 4) закончить выводом.`,
  obr:``,body:``,
  key:'Критерии: есть определение нормы (принятый образец литературного произношения); не меньше трёх примеров с верной транскрипцией или пометой; назван вид ошибок; есть вывод; 6–8 предложений, мысль развивается последовательно.<br>Образец: Люди в разных краях России говорят немного по-разному. Чтобы все понимали друг друга, в литературном языке есть орфоэпическая норма — принятый образец произношения. Норма подсказывает, что нужно говорить [што], а не [ч\'то], [кан\'э́шна], а не [кан\'э́ч\'на], [кафэ́], а не [каф\'э́]. Чаще всего ошибаются, когда читают слово по буквам. Бывают и просторечные ошибки: «колидор», «транвай». Когда человек говорит по норме, его слушают, а не поправляют. Поэтому единая норма нужна всем, кто хочет, чтобы его речь была понятной и грамотной.'},
 {n:11,l:1,st:5,task:`Тонкость. Лингвистическая задача. Прочитать сведения и ответить на вопросы: 1) Какое произношение ближе к написанию — московское или петербургское? 2) Почему сегодня в словарях у слов «булочная», «молочный» два допустимых варианта, а у слова «конечно» — один? 3) Привести два слова, в которых [шн] обязательно, и два похожих слова, в которых возможно только [ч'н].`,
  obr:``,
  body:`В XIX веке москвичи говорили «було[шн]ая», «моло[шн]ый», «коне[шн]о», а петербуржцы — «було[ч'н]ая», «моло[ч'н]ый», но тоже «коне[шн]о». Постепенно в большинстве слов победило произношение [ч'н].`,
  key:'1) Петербургское: [ч\'н] соответствует буквам чн.<br>2) Произношение «булочной» и «молочного» меняется на наших глазах: старшая (московская) норма [шн] ещё жива, а младшая [ч\'н] уже стала основной, поэтому словари признают оба варианта. В слове «конечно» [шн] сохранилось во всех городах — вариант [ч\'н] не принят.<br>3) [шн]: конечно, скучно (также нарочно, яичница, скворечник, отчества на -ична). [ч\'н]: конечный, бесконечный (также точный, вечный).'},
// ── Урок 2. Произношение гласных
 {n:12,l:2,st:1,task:`Записать транскрипцию слов, поставить ударение. Подчеркнуть [а] на месте буквы о.`,
  obr:`Корова — [каро́ва]: о в первом слоге без ударения звучит как [а].`,
  body:`Погода, ворона, холодок, потолок, собака, морковка, голубой, пароход, облако, работа, колобок, топор.`,
  key:'[паго́да], [варо́на], [халадо́к], [патало́к], [саба́ка], [марко́фка], [галубо́й\'], [парахо́т], [о́блака], [рабо́та], [калабо́к], [тапо́р].'},
 {n:13,l:2,st:1,task:`Записать транскрипцию слов, поставить ударение. Подчеркнуть [и] на месте безударных е и я.`,
  obr:`Мешок — [м'ишо́к]: е без ударения после мягкого [м'] звучит как [и].`,
  body:`Пятёрка, сестрица, веснушка, дятел, метель, рябина, несу, лягушка, петух, ремень, теплица, телега.`,
  key:'[п\'ит\'о́рка], [с\'истр\'и́ца], [в\'исну́шка], [д\'а́т\'ил], [м\'ит\'э́л\'], [р\'иб\'и́на], [н\'ису́], [л\'игу́шка], [п\'иту́х], [р\'им\'э́н\'], [т\'ипл\'и́ца], [т\'ил\'э́га].'},
 {n:14,l:2,st:2,task:`Записать транскрипцию слов. Подчеркнуть гласный звук после ж, ш, ц. Объяснить, почему на месте е без ударения звучит [ы], а на месте а — [а].`,
  obr:`Жених — [жын'и́х]: [ж] всегда твёрдый, поэтому е без ударения после него звучит как [ы].`,
  body:`Цепной, шевелить, желать, шеренга, шершавый, шатёр, шалить, жильё, цедить, шипеть, цыплёнок, шептун.`,
  key:'[цыпно́й\'], [шыв\'ил\'и́т\'], [жыла́т\'], [шыр\'э́нга], [шырша́вый\'], [шат\'о́р], [шал\'и́т\'], [жыл\'й\'о́], [цыд\'и́т\'], [шып\'э́т\'], [цыпл\'о́нак], [шыпту́н].<br>[ж], [ш], [ц] всегда твёрдые, поэтому гласные после них звучат как после твёрдых: е — [ы], а и о — [а], и — [ы].'},
 {n:15,l:2,st:2,task:`Распределить слова в три столбика по звуку, который произносится на месте безударной гласной: [а], [и], [ы]. Поставить ударение.`,
  obr:`Поро́г — [а]: о без ударения после твёрдого согласного.`,
  body:`Пожар, часок, сосед, жилец, метла, щегол, гнездо, носок, шажок, шептала, жестянка, берёт.`,
  key:'[а]: пожа́р, сосе́д, носо́к, шажо́к.<br>[и]: часо́к, метла́, щего́л, гнездо́, берёт.<br>[ы]: жиле́ц, шепта́ла, жестя́нка.'},
 {n:16,l:2,st:2,task:`Найти в каждом ряду слово, в котором на месте безударной гласной звучит не тот звук, что в остальных. Объяснить выбор.`,
  obr:`Ряд «гора, трава, река, вода» — лишнее «река»: на месте е звучит [и], в остальных — [а].`,
  body:`Ряды:<br>А) дрова, лопата, мешок, сова<br>Б) пятак, часы, жара, метла<br>В) жена, цена, шесток, сестра<br>Г) шагать, шалун, щадить, шакал<br>Д) окно, оса, озёра, ещё<br>Е) цепной, червяк, цедить, целебный`,
  key:'А) мешок — [и] (в остальных [а]). Б) жара — [а] (в остальных [и]). В) сестра — [и] (в остальных [ы] после ж, ц, ш). Г) щадить — [и] после щ (в остальных [а] после ш). Д) ещё — [й\'и] (в остальных [а]). Е) червяк — [и] после ч (в остальных [ы] после ц).'},
 {n:17,l:2,st:3,task:`Прочитать стихи вслух. 1) Записать транскрипцию слов «золотая», «весёлым», «журавли», «печально», «пролетая». 2) Выписать слова, в которых на месте буквы о без ударения звучит [а]. 3) Выписать слова, в которых е без ударения после мягкого согласного звучит как [и].`,
  obr:`Золотая: о — [а], о — [а].`,
  body:`Отговорила роща золотая / Берёзовым, весёлым языком, / И журавли, печально пролетая, / Уж не жалеют больше ни о ком. (С. А. Есенин, «Отговорила роща золотая…»)`,
  key:'1) [залата́й\'а], [в\'ис\'о́лым], [журавл\'и́], [п\'ич\'а́л\'на], [прал\'ита́й\'а].<br>2) Отговорила, золотая, берёзовым, печально, пролетая, о (ни о ком).<br>3) Берёзовым, весёлым, печально, пролетая, не (не жалеют). (В слове «языком» я стоит в начале слова и обозначает два звука [й\'и].)'},
 {n:18,l:2,st:3,task:`Прочитать стихи. 1) Выписать слова с безударными о, е, я и указать, какой звук произносится на их месте. 2) Записать транскрипцию слов «навек», «полюбил», «берёзки», «сарафан».`,
  obr:`Полюбил: о — [а].`,
  body:`Я навек за туманы и росы / Полюбил у берёзки стан, / И её золотистые косы, / И холщовый её сарафан. (С. А. Есенин, «Ты запой мне ту песню, что прежде…») Пояснения: стан — фигура человека; холщовый — из холста, грубой льняной ткани.`,
  key:'1) Полюбил (о — [а]), берёзки (е — [и]), её (е в начале слова — [й\'и]), золотистые (о — [а], о — [а]), холщовый (о — [а]).<br>2) [нав\'э́к], [пал\'уб\'и́л], [б\'ир\'о́ск\'и], [сарафа́н].'},
 {n:19,l:2,st:3,task:`Записать транскрипцию пар. Подчеркнуть гласный, который в одном слове ударный, а в другом — безударный. Сделать вывод: где гласный звучит ясно?`,
  obr:`Нос — носы: [но́с] — [насы́].`,
  body:`Стол — стола; мяч — мячи; шест — шеста; дом — домой; звёзды — звезда; жёлтый — желтизна; частый — частота; пляска — плясун.`,
  key:'[сто́л] — [стала́]; [м\'а́ч\'] — [м\'ич\'и́]; [шэ́ст] — [шыста́]; [до́м] — [дамо́й\']; [зв\'о́зды] — [зв\'изда́]; [жо́лтый\'] — [жылт\'изна́]; [ч\'а́стый\'] — [ч\'истата́]; [пл\'а́ска] — [пл\'ису́н].<br>Вывод: ясно гласный звучит только под ударением. Без ударения о звучит как [а]; е и я после мягких и а после ч — как [и]; е после ж, ш — как [ы].'},
 {n:20,l:2,st:2,task:`Ученик записал транскрипцию слов. Определить, какие это слова, найти ошибки и записать правильно. Есть и верные записи.`,
  obr:`[сова́] — ошибка: сова — [сава́].`,
  body:`Записи:<br>А) [высото́]<br>Б) [м'эха́]<br>В) [окно́]<br>Г) [гара́]<br>Д) [цэха́]<br>Е) [т'ану́т']<br>Ж) [й'азы́к]<br>З) [ч'асы́]<br>И) [кара́]<br>К) [п'ила́]`,
  key:'А) высота — [высата́]. Б) меха — [м\'иха́]. В) окно — [акно́]. Г) гора — верно. Д) цеха — [цыха́]. Е) тянуть — [т\'ину́т\']. Ж) язык — [й\'изы́к]. З) часы — [ч\'исы́]. И) кора — верно. К) пила — верно.'},
 {n:21,l:2,st:3,task:`1) Записать транскрипцию слов; подчеркнуть [й'и] на месте е или я. 2) Прочитать сочетания слов вслух и указать, какой звук произносится на месте и в начале второго слова.`,
  obr:`Ягнёнок — [й'игн'о́нак].`,
  body:`Слова: язычок, ячмень, единица, ежевика, яйцо, поедим, съедим, маяки.<br>Сочетания: с игрушкой, от избы, под ивой, к играм, над избой, в историю.`,
  key:'1) [й\'изыч\'о́к], [й\'ич\'м\'э́н\'], [й\'ид\'ин\'и́ца], [й\'ижыв\'и́ка], [й\'ий\'цо́], [пай\'ид\'и́м], [сй\'ид\'и́м], [май\'ик\'и́].<br>2) Везде на месте и звучит [ы]: предыдущее слово кончается твёрдым согласным и сливается со следующим: [сы]грушкой, о[ты]збы, по[ды]вой, [кы]грам, на[ды]збой, [вы]сторию.'},
 {n:22,l:2,st:3,task:`Записать буквами слова по транскрипции. Подчеркнуть буквы, которые обозначают не тот звук, что слышится. В каком слове таких букв нет?`,
  obr:`[в'исна́] — весна: на месте е слышится [и].`,
  body:`[кал'исо́], [в'идро́], [маро́с], [гаро́х], [жыл'э́зный'], [шаги́], [ч'ирн'и́ла], [дама́].`,
  key:'Колесо (о, е), ведро (е), мороз (первая о, з), горох (первая о), железный (первая е), шаги — расхождений нет (а после ш без ударения звучит [а]), чернила (е), дома (о).'},
 {n:23,l:2,st:2,task:`Записать транскрипцию слов. Посчитать, сколько раз в каждом слове произносится звук [а] и сколько раз — звук [и].`,
  obr:`Борода — [барада́]: [а] — 3 раза, [и] — ни разу.`,
  body:`Огородник, колокольчик, перепёлка, сковорода, черепаха, тетрадка, веретено, самолётик.`,
  key:'[агаро́дн\'ик] — [а] 2, [и] 1. [калако́л\'ч\'ик] — [а] 2, [и] 1. [п\'ир\'ип\'о́лка] — [а] 1, [и] 2. [скаварада́] — [а] 4, [и] 0. [ч\'ир\'ипа́ха] — [а] 2, [и] 2. [т\'итра́тка] — [а] 2, [и] 1. [в\'ир\'ит\'ино́] — [а] 0, [и] 3. [самал\'о́т\'ик] — [а] 2, [и] 1.'},
 {n:24,l:2,st:4,task:`Прочитать стихи вслух. 1) Записать транскрипцию слов «соловей», «желтеет», «запеть», «полдень», «смородинном». 2) Найти слово, в котором после ж на месте е без ударения звучит [ы]. 3) Найти слова, в которых буква е обозначает два звука [й'и].`,
  obr:``,
  body:`Едва лишь в полдень солнце греет, / Краснеет липа в высоте, / Сквозя, березник чуть желтеет, / И соловей ещё не смеет / Запеть в смородинном кусте. (А. А. Фет, «Ещё весны душистой нега…») Пояснения: березник — берёзовая роща.`,
  key:'1) [салав\'э́й\'], [жылт\'э́й\'ит], [зап\'э́т\'], [по́лд\'ин\'], [смаро́д\'иным].<br>2) Желтеет.<br>3) В начале слова: едва — [й\'идва́], ещё — [й\'ищ\'о́]; после гласной: греет, краснеет, желтеет, смеет (вторая е — [й\'и]).'},
 {n:25,l:2,st:4,task:`Прочитать стихи. 1) Выписать слова, в которых после ч на месте а или е без ударения звучит [и]. 2) Выписать слова, где о без ударения звучит как [а]. 3) Записать транскрипцию слов «короткая», «вечера», «холодный», «серпом».`,
  obr:``,
  body:`1. Есть в осени первоначальной / Короткая, но дивная пора — / Весь день стоит как бы хрустальный, / И лучезарны вечера… (Ф. И. Тютчев, «Есть в осени первоначальной…»)<br>2. И месяц холодный стоит, не сгорая, / Зелёным серпом в синеве. (А. А. Блок, «Эхо»)<br>Пояснения: лучезарный — сияющий, полный света.`,
  key:'1) Лучезарны ([луч\'иза́рны]), вечера ([в\'ич\'ира́]).<br>2) Первоначальной, короткая, пора, стоит (оба раза), холодный, сгорая; но — [на].<br>3) [каро́ткай\'а], [в\'ич\'ира́], [хало́дный\'], [с\'ирпо́м].'},
 {n:26,l:2,st:5,task:`Тонкость. В научной транскрипции безударные гласные после твёрдых согласных записывают точнее: [ʌ] — в первом слоге перед ударным и в начале слова, [ъ] — в остальных безударных слогах. Сравнить: голова [галава́] — [гълʌва́]; молоко [малако́] — [мълʌко́]. Записать научной транскрипцией слова из списка и объяснить, почему в начале слова пишется [ʌ].`,
  obr:``,
  body:`Подошла, огород, хорошо, самовар, сковорода — эти слова записать научной транскрипцией.`,
  key:'[пъдʌшла́], [ʌгʌро́т], [хърʌшо́], [съмʌва́р], [скъвърʌда́]. В начале слова на месте о и а в любом безударном слоге звучит [ʌ], а не краткий [ъ] (по Н. В. Адамчик и научной традиции; Д. Э. Розенталь пишет здесь [ъ] и [а]). В школьной записи все эти звуки обозначают [а].'},
 {n:27,l:6,st:5,os:'диктант',task:`Записать текст под диктовку. Затем: 1) над безударными гласными в словах «осенний», «сестрой», «молодые», «засмеялась», «колючий» надписать звук, который произносится; 2) выписать слова, в которых после ш или ж на месте е без ударения звучит [ы]; 3) выписать слова, в которых после ч или щ на месте а или е без ударения звучит [и].`,
  obr:``,
  body:`Осенний лес. Ранним утром мы с сестрой пошли к реке. Над водой ещё висел туман, и лучи едва пробивались сквозь него. Шелестели желтеющие листья. На опушке шептались молодые осинки. Вдруг из-за пня выскочил ёжик и побежал к норе. Сестра засмеялась: колючий шалун совсем не боялся людей. Мы постояли с часок, послушали, как щебечут синицы, и тихо пошли домой — к горячему чаю.`,
  key:'1) Осенний — [а] на месте о (е — ударная); сестрой — [и]; молодые — [а], [а]; засмеялась — [а] на месте первой а, [и] на месте е; колючий — [а].<br>2) Шелестели, желтеющие, шептались.<br>3) Часок, щебечут, горячему.'},
// ── Урок 3. Произношение согласных
 {n:28,l:3,st:1,task:`Вспомним: глава «Звуки и буквы», урок «Оглушение и озвончение. Транскрипция». Записать транскрипцию слов. Подчеркнуть согласные, которые оглушаются или озвончаются.`,
  obr:`Лодка — [ло́тка]: д перед глухим [к] оглушается.`,
  body:`Сдал, отбор, друг, берёзка, флажки, сбежать, повод, дубки, отгадка, наряд, подписка, обход.`,
  key:'[зда́л], [адбо́р], [дру́к], [б\'ир\'о́ска], [флашк\'и́], [зб\'ижа́т\'], [по́ват], [дупк\'и́], [адга́тка], [нар\'а́т], [патп\'и́ска], [апхо́т]. Мягкость первого согласного ([з\'б\'], [з\'д\'], [т\'п\']) — не ошибка: это допустимый вариант.'},
 {n:29,l:3,st:1,task:`Выписать слова с непроизносимыми согласными и зачеркнуть букву, которая не произносится. Слова, в которых все согласные произносятся, выписать отдельно.`,
  obr:`Вестник — т не произносится. Весть — все согласные произносятся.`,
  body:`Местность, известие, свистнуть, поздний, окрестность, грустно, опасный, вкусный, радостный, капустник, прелестный, хвастать, ровесник, звездочёт.`,
  key:'Непроизносимые: местность (т), свистнуть (т), поздний (д), окрестность (т в сочетании стн), грустно (т), радостный (т), капустник (т), прелестный (т).<br>Все согласные произносятся: известие, опасный, вкусный, хвастать, ровесник, звездочёт.'},
 {n:30,l:3,st:2,task:`Распределить слова по сочетаниям: стн, здн, лнц, рдц, вств, стл, ндск. Зачеркнуть букву, которая не произносится. Одно слово лишнее — объяснить почему.`,
  obr:`Местный — стн: т не произносится.`,
  body:`Властный, уездный, солнцепёк, сердцебиение, здравствовать, завистливый, шотландский, безвестный, совестливый, чувствительный, бездельник, сердцевина.`,
  key:'стн: властный, безвестный (т). здн: уездный (д). лнц: солнцепёк (л). рдц: сердцебиение, сердцевина (д). вств: здравствовать, чувствительный (первая в). стл: завистливый, совестливый (т). ндск: шотландский (д).<br>Лишнее — бездельник: в нём нет непроизносимого согласного, все звуки произносятся.'},
 {n:31,l:3,st:2,task:`Записать транскрипцию слов. Подчеркнуть буквы, которыми обозначен звук [щ']. Найти слова, где на месте двух букв звучит не [щ'], а [ч'].`,
  obr:`Счёт — [щ'о́т]: сч звучит как [щ'].`,
  body:`Считалка, счётчик, щука, обидчик, песчаный, буфетчик, сварщик, мужчины.`,
  key:'[щ\'ита́лка], [щ\'о́ч\'ик], [щ\'у́ка], [аб\'и́ч\'ик], [п\'ищ\'а́ный\'], [буф\'э́ч\'ик], [сва́рщ\'ик], [мущ\'и́ны].<br>[щ\'] обозначают сч, зч, жч и буква щ. На месте двух букв звучит [ч\']: обидчик (дч), буфетчик (тч), счётчик (тч во второй части слова).'},
 {n:32,l:3,st:2,task:`Прочитать предложения вслух. Выписать слова с тся и ться и записать их транскрипцию. Есть ли разница в произношении тся и ться?`,
  obr:`Учится — [у́ч'ица].`,
  body:`Предложения:<br>1. Кажется, снегопад кончился.<br>2. Река разливается.<br>3. Ребята собираются в поход и долго не могут решить, кому нести котелок.<br>4. Нам нужно торопиться.<br>5. Утром не хочется вставать.<br>6. Над крышей вьётся снег, и скоро весь двор станет белым.<br>7. Пора готовиться к соревнованиям.`,
  key:'Кажется [ка́жыца], разливается [разл\'ива́й\'ица], собираются [саб\'ира́й\'уца], торопиться [тарап\'и́ца], хочется [хо́ч\'ица], вьётся [в\'й\'о́ца], готовиться [гато́в\'ица].<br>Разницы нет: тся и ться произносятся одинаково — [ца].'},
 {n:33,l:3,st:2,task:`Прочитать сочетания слов. Подчеркнуть букву г там, где на её месте звучит [х] или [в], и надписать звук. Слова, в которых г звучит как [г], выписать отдельно.`,
  obr:`Мягче — на месте г звучит [х].`,
  body:`Мягкое кресло, легко ответить, у старого дуба, мягче воска, легче пёрышка, много снега, строгий учитель, ничего страшного, сегодня вечером, дорогой гость, белого голубя, нет никого.`,
  key:'[х]: мягкое, легко, мягче, легче. [в]: старого, ничего, страшного, сегодня, белого, никого.<br>[г]: много, снега, строгий, дорогой, гость, голубя.'},
 {n:34,l:3,st:3,task:`Прочитать предложения вслух. Выписать слова, в которых произношение согласных расходится с написанием: непроизносимые согласные, сочетания, которые звучат одним звуком, гк, г в -ого и в слове «его». Объяснить произношение.`,
  obr:`Чувство — первый в не произносится.`,
  body:`Предложения:<br>1. Странное чувство тотчас овладело мной. (И. С. Тургенев, «Бежин луг»)<br>2. Детские звонкие голоса раздались вокруг огней; два-три мальчика быстро поднялись с земли. (И. С. Тургенев, «Бежин луг»)<br>3. Его душе вдруг стало легко; казалось, всё развязалось у него. (Н. В. Гоголь, «Тарас Бульба»)<br>4. Читатель легко может себе представить, что я не был совершенно хладнокровен. (А. С. Пушкин, «Капитанская дочка»)<br>5. Синяя вода кажется густою, как масло, винт парохода работает в ней мягко и почти бесшумно. (М. Горький, «Сказки об Италии»)<br>6. Как мало в этой жизни надо / Нам, детям, — и тебе и мне. / Ведь сердце радоваться радо / И самой малой новизне. (А. А. Блок, «Ты помнишь? В нашей бухте сонной…»)`,
  key:'1. Чувство — первый в не произносится; тотчас — тч звучит как долгий [ч\'].<br>2. Детские — тс звучит как [ц].<br>3. Его, него — г звучит как [в]; легко — гк звучит как [хк].<br>4. Легко — [хк]; что — [шт] (урок 4).<br>5. Кажется — тся звучит как [ца]; мягко — [хк]; бесшумно — сш звучит как долгий [шш].<br>6. Сердце — д не произносится; радоваться — ться звучит как [ца].'},
 {n:35,l:3,st:3,task:`Прочитать пары слов. Подчеркнуть слово, в котором выделяемый согласный (л, т, д) произносится. Объяснить, как родственное слово помогает правильно написать слово с непроизносимым согласным.`,
  obr:`Сердце — сердечко: в слове «сердечко» [д] слышен.`,
  body:`Солнце — солнышко; честный — честь; поздно — опоздать; грустный — грусть; известный — известие; звёздный — звезда; местный — место; вестник — весть; ненастный — ненастье.`,
  key:'Согласный произносится: солнышко (л), честь (т), опоздать (д), грусть (т), известие (т), звезда (д), место (т), весть (т), ненастье (т).<br>В словах с сочетаниями лнц, стн, здн согласный не звучит, но пишется. Его проверяют родственным словом, где этот согласный слышен.'},
 {n:36,l:3,st:3,task:`Записать транскрипцию слов. Подчеркнуть сочетания букв, которые произносятся одним (часто долгим) звуком. Затем указать, долгий или обычный звук произносится на месте двойных согласных.`,
  obr:`Сшить — [шшы́т']: сш звучит как долгий [шш].`,
  body:`Слова: бесшумный, разжечь, без жара, расшатать, братство, флотский, заводской, наводчик, сжатый.<br>Двойные согласные: касса, грамм, ванна, металл, сумма, аллея.`,
  key:'[б\'ишшу́мный\'] (сш), [ражжэ́ч\'] (зж), [б\'ижжа́ра] (з ж), [рашшата́т\'] (сш), [бра́цтва] (тс), [фло́цк\'ий\'] (тс), [завацко́й\'] (дс), [наво́ч\'ик] (дч), [жжа́тый\'] (сж).<br>Двойные: касса, ванна, сумма — долгий звук (после ударного); грамм, металл (на конце), аллея (перед ударным) — обычный.'},
 {n:37,l:3,st:4,task:`Найти в каждом ряду лишнее слово — то, в котором нет общего для ряда произношения. Объяснить выбор.`,
  obr:``,
  body:`Ряды:<br>А) честный, местный, тесный, грустный<br>Б) счёт, считать, щука, сшить<br>В) учится, умыться, купаться, братство<br>Г) мягкий, лёгкий, мягко, мягок<br>Д) его, синего, сегодня, много<br>Е) праздник, сердце, чувство, баловство`,
  key:'А) тесный — в нём нет сочетания стн, т произносится; в остальных т пишется, но не произносится. Б) сшить — [шш], в остальных [щ\']. В) братство — тс звучит как [ц], но сочетания [ца] нет; в остальных тся, ться звучат как [ца]. Г) мягок — г стоит перед гласным и звучит как [г], в остальных гк — [хк]. Д) много — г звучит как [г], в остальных — [в]. Е) баловство — в сочетании вств на месте в звучит [ф]: [балафство́]; в остальных один согласный не произносится.'},
 {n:38,l:3,st:4,task:`Ученик записал транскрипцию слов. Найти ошибки, исправить и объяснить. Есть и верные записи.`,
  obr:``,
  body:`Записи:<br>А) местный [м'э́стный']<br>Б) поздно [по́здна]<br>В) учится [у́ч'итс'а]<br>Г) мягко [м'а́кка]<br>Д) счёт [щ'о́т]<br>Е) его [й'иго́]<br>Ж) детский [д'э́тск'ий']<br>З) грустный [гру́сный']<br>И) дуб [ду́б]<br>К) сшить [сшы́т']`,
  key:'А) ошибка: т не произносится — [м\'э́сный\']. Б) ошибка: д не произносится — [по́зна]. В) ошибка: тся звучит как [ца] — [у́ч\'ица]. Г) ошибка: гк — [хк] — [м\'а́хка]. Д) верно. Е) ошибка: г звучит как [в] — [й\'иво́]. Ж) ошибка: тс — [ц] — [д\'э́цк\'ий\']. З) верно. И) ошибка: на конце оглушение — [ду́п]. К) ошибка: сш — долгий [шш] — [шшы́т\'].'},
 {n:39,l:3,st:3,task:`Посчитать в каждом слове буквы и звуки. Объяснить, почему их число не совпадает.`,
  obr:`Местный — 7 букв, 6 звуков: т не произносится.`,
  body:`Чувствовать, радостный, счастливый, поздно, сердце, лёгкий, детский, счёт, здравствуй, праздник.`,
  key:'Чувствовать — 11 букв, 9 звуков (первая в не произносится, ь звука не обозначает). Радостный — 9 букв, 8 звуков (т). Счастливый — 10 букв, 8 звуков (сч — один звук [щ\'], т не произносится). Поздно — 6 букв, 5 звуков (д). Сердце — 6 букв, 5 звуков (д). Лёгкий — 6 букв, 6 звуков [л\'о́хк\'ий\']: г звучит как [х], число не меняется. Детский — 7 букв, 6 звуков (тс — один звук [ц]). Счёт — 4 буквы, 3 звука (сч — [щ\']). Здравствуй — 10 букв, 9 звуков (первая в). Праздник — 8 букв, 7 звуков (д).'},
 {n:40,l:3,st:4,task:`Прочитать стихи вслух. 1) Выписать слова, в которых тся и ться звучат как [ца]. 2) Найти слово с сочетанием гч и записать, как оно произносится. 3) Найти слово, в котором г произносится как [в]. 4) Записать транскрипцию слова «ложится».`,
  obr:``,
  body:`1. Заря прощается с землёю, / Ложится пар на дне долин, / Смотрю на лес, покрытый мглою, / И на огни его вершин. (А. А. Фет, «Заря прощается с землёю…»)<br>2. Ты поймёшь, как в этом море / Облегчается душа, / И какие гаснут зори / За грядою камыша. (А. А. Блок, «Милый брат! Завечерело…»)`,
  key:'1) Прощается, ложится, облегчается.<br>2) Облегчается — гч звучит как [хч\'].<br>3) Его — [й\'иво́].<br>4) [лажы́ца].'},
 {n:41,l:3,st:4,task:`Подготовиться к чтению вслух. Найти и выписать все места, где произношение согласных расходится с написанием, и указать, как они звучат. Прочитать отрывок вслух, соблюдая нормы.`,
  obr:``,
  body:`Предложения:<br>1. Небольшая ночная птица, неслышно и низко мчавшаяся на своих мягких крыльях, почти наткнулась на меня и пугливо нырнула в сторону. (И. С. Тургенев, «Бежин луг»)<br>2. Цвет небосклона, лёгкий, бледно-лиловый, не изменяется во весь день и кругом одинаков; нигде не темнеет, не густеет гроза… (И. С. Тургенев, «Бежин луг»)`,
  key:'Низко — з перед глухим звучит как [с]. Мчавшаяся — в перед глухим [ш] звучит как [ф]. Мягких — гк звучит как [хк\']. Лёгкий — гк звучит как [хк]. Изменяется — тся звучит как [ца]. В сторону — в перед глухим [с] звучит как [ф]. Одинаков — в на конце слова звучит как [ф]. Кругом — г произносится как [г]: это не сочетание -ого. Кроме того: почти — чт звучит как пишется, [ч\'т]; ночная — [ч\'н] (урок 4).'},
 {n:42,l:3,st:3,task:`Подобрать и записать по три слова на каждое правило произношения согласных: 1) стн (т не произносится); 2) сч или зч ([щ']); 3) тся или ться ([ца]); 4) гк ([хк]); 5) г в -ого, -его ([в]). Слова из урока не брать. Записать транскрипцию одного слова из каждой группы.`,
  obr:`1) Участник — [уч'а́сн'ик]: т не произносится.`,body:``,
  key:'Например: 1) участник, окрестный, хвастнуть — [уч\'а́сн\'ик]; 2) считанный, счётный, счастливец — [щ\'о́тный\']; 3) моется, строится, улыбаться — [мо́й\'ица]; 4) мягкость, лёгкость, мягкая — [м\'а́хкай\'а]; 5) нового, тёплого, чужого — [но́вава]. Мягкость первого согласного в сочетаниях (например, [с\'н\']) — не ошибка. Принимаются любые верные примеры.'},
 {n:43,l:6,st:5,task:`Тонкость. Мини-исследование по орфоэпическому словарю. Для каждого слова выяснить, есть ли у него два допустимых варианта произношения, и записать их. Объяснить, почему такие слова не берут в задания с одним ответом.`,
  obr:``,
  body:`Здесь, снег, песня, гвоздь, дождь, езжу, вожжи, учусь, остался, исчезнуть.`,
  key:'Здесь — [з\'д\'] и [зд\'] (смягчение перед мягким согласным); снег, песня — [с\'н\'] и [сн\']; гвоздь — [с\'т\'] и [ст\'] на конце; дождь — [шт\'] по написанию и старомосковское [щ\']; езжу, вожжи — долгий твёрдый [жж] и старое долгое мягкое [ж\'ж\']; учусь, остался — конечное мягкое [с\'] и старое твёрдое [с]; исчезнуть — [щ\'] и [щ\'ч\'].<br>Если верны оба варианта, у задания нет одного ответа: ученик, выбравший второй вариант, тоже прав.'},
 {n:44,l:6,st:5,os:'диктант',task:`Записать текст под диктовку. Затем: 1) подчеркнуть буквы, обозначающие непроизносимые согласные; 2) выписать слова, в которых тся и ться звучат как [ца]; 3) выписать слова, где г звучит как [в] или [х]; 4) найти слово с сочетанием сч и записать, как оно произносится.`,
  obr:``,
  body:`Праздник в лесу. Сегодня солнце встало рано. Лёгкий ветер качает ветки, и кажется, что деревья здороваются друг с другом. На поляне собираются птицы. Счастливые синицы перелетают с ветки на ветку. Мягкий мох пружинит под ногами. Где-то стучит дятел. Хочется идти и идти, слушать и смотреть. Честное слово, нет ничего чудеснее утреннего леса!`,
  key:'1) Праздник (д), солнце (л), счастливые (т), честное (т).<br>2) Кажется, здороваются, собираются, хочется.<br>3) [в]: сегодня, ничего, утреннего; [х]: лёгкий, мягкий.<br>4) Счастливые — сч звучит как [щ\'].'},
// ── Урок 4. Сочетания чн и чт
 {n:45,l:4,st:1,task:`Распределить слова в два столбика: чн произносится как [ч'н]; чн произносится как [шн].`,
  obr:`Вечный — [ч'н]; Никитична — [шн].`,
  body:`Сочный, речной, дачный, Кузьминична, Саввична, отлично, мучной, Лукинична, лучник, научный, яичница, скворечник, срочно, Ильинична, качнулся, звучный.`,
  key:'[ч\'н]: сочный, речной, дачный, отлично, мучной, лучник, научный, срочно, качнулся, звучный.<br>[шн]: Кузьминична, Саввична, Лукинична, яичница, скворечник, Ильинична.'},
 {n:46,l:4,st:1,task:`Распределить слова в два столбика: чт произносится как [шт]; чт произносится как [ч'т]. Подчеркнуть слово, которое похоже на «что», но произносится с [ч'т].`,
  obr:`Чтобы — [шт]; почта — [ч'т].`,
  body:`Что, кое-что, мачта, нечто, ни за что, почтальон, мечта, чтение, что-нибудь, почтенный, мечтательный, что-то, почтамт.`,
  key:'[шт]: что, кое-что, ни за что, что-нибудь, что-то.<br>[ч\'т]: мачта, нечто, почтальон, мечта, чтение, почтенный, мечтательный, почтамт.<br>Подчеркнуть: нечто.'},
 {n:47,l:4,st:2,task:`Прочитать пары вслух. Подчеркнуть слова, в которых чн произносится как [шн]. Объяснить, почему похожие по звучанию слова произносятся по-разному.`,
  obr:`Саввична — [шн] (отчество); пятничный — [ч'н].`,
  body:`Конечно — конечный; Кузьминична — звучно; Никитична — непрочно; яичница — пшеничный; скворечник — встречный; Фоминична — отлично; Лукинична — кирпичный; Саввична — пятничный.`,
  key:'[шн]: конечно, Кузьминична, Никитична, яичница, скворечник, Фоминична, Лукинична, Саввична. Во вторых словах пар — [ч\'н].<br>[шн] сохранилось только в коротком списке слов и в отчествах на -ична. Похожие слова, которые в список не входят (конечный, кирпичный, непрочно), произносятся по написанию.'},
 {n:48,l:4,st:2,task:`Образовать от имён женские отчества (на -ична) и мужские (на -ич). Записать, как произносится сочетание чн в женских отчествах. Составить два предложения с любыми отчествами.`,
  obr:`Илья — Ильинична [шн], Ильич.`,
  body:`Имена: Никита, Фома, Кузьма, Савва, Лука, Илья.`,
  key:'Никитична — Никитич; Фоминична — Фомич; Кузьминична — Кузьмич; Саввична — Саввич; Лукинична — Лукич; Ильинична — Ильич. В женских отчествах чн произносится как [шн]: Никити[шн]а.<br>Предложения, например: Ольга Никитична — наш классный руководитель. Анна Кузьминична испекла пирог.'},
 {n:49,l:4,st:3,task:`Прочитать предложения. Выписать слова с сочетаниями чн и чт и указать, как они произносятся. Найти в предложении 4 слово с сочетанием сч и указать его произношение.`,
  obr:`Что — [шт].`,
  body:`Предложения:<br>1. Что ни рассказывай, а всё, однако же, скучно, — говорил, идя позади их, Платонов. (Н. В. Гоголь, «Мёртвые души»)<br>2. Ему стало ясно, что она не скоро уступит, он же, конечно, не мог уступить. (М. Горький, «Сказки об Италии»)<br>3. Пересмотрю нарочно, сколько у меня денег. (Н. В. Гоголь, «Ревизор»)<br>4. Впрочем, все эти люди были тоже, как нарочно, в самом счастливом настроении в этот вечер и весьма довольны собой. (Ф. М. Достоевский, «Идиот»)<br>5. Татьяна Ильинична потупилась, улыбнулась и покраснела. (И. С. Тургенев, «Записки охотника»)<br>6. Смиренная Прасковья Ильинична, моя тётушка, разливала чай. (Ф. М. Достоевский, «Село Степанчиково и его обитатели»)`,
  key:'1. Что — [шт]; скучно — [шн]. 2. Что — [шт]; конечно — [шн]. 3. Нарочно — [шн]. 4. Нарочно — [шн]; счастливом — сч звучит как [щ\'], т не произносится. 5. Ильинична — [шн]. 6. Ильинична — [шн].'},
 {n:50,l:4,st:3,task:`Прочитать записку. Найти слова, написанные «как слышится». Исправить ошибки и объяснить, почему так писать нельзя.`,
  obr:`«Штобы» — ошибка: пишется «чтобы», хотя произносится [шт].`,
  body:`«Мама, я ушёл к Анне Ильинишне за книгой. Конешно, вернусь к обеду. На плите яишница — это тебе. Штобы не было скушно, я оставил на столе журнал. Если позвонит Никитишна, скажи, что я нарошно не взял телефон: он почти разрядился.»`,
  key:'Ильиничне, конечно, яичница, чтобы, скучно, Никитична, нарочно. В этих словах произносится [шн] или [шт], но пишется чн и чт: произношение на письмо не переносится. (Слово «почти» написано верно.)'},
 {n:51,l:4,st:3,task:`Записать транскрипцию слов. Подчеркнуть звуки на месте чн и чт.`,
  obr:`Вечный — [в'э́ч'ный'].`,
  body:`Прочный, звучный, Никитична, срочный, почта, мечта, что-то, почтамт, ночник, Фоминична.`,
  key:'[про́ч\'ный\'], [зву́ч\'ный\'], [н\'ик\'и́т\'ишна], [сро́ч\'ный\'], [по́ч\'та], [м\'ич\'та́], [што́та], [пач\'та́мт], [нач\'н\'и́к], [фам\'и́н\'ишна].'},
 {n:52,l:4,st:3,task:`Прочитать предложения. Выписать слова с сочетаниями чн и чт в четыре столбика: [ч'н], [шн], [шт], [ч'т].`,
  obr:`Почту — [ч'т].`,
  body:`Предложения:<br>1. Нет, точного ничего, — ответил я, — конечно, ничего. (Ф. М. Достоевский, «Игрок»)<br>2. Тогда произошло нечто необыкновенное. (И. С. Тургенев, «Записки охотника»)<br>3. Это было скучно, как обедня, и тянулось изо дня в день, точно лихорадка. (М. Горький, «Сказки об Италии»)<br>4. Пойдёмте, — сказал он, заглянув ей в лицо, чтоб убедиться, что ей точно было не скучно. (Л. Н. Толстой, «Анна Каренина»)<br>5. Приносят ко мне на почту письмо. (Н. В. Гоголь, «Ревизор»)<br>6. Это была уже не мечта, не гадание, а действительность, начавшая совершаться. (Ф. М. Достоевский, «Дневник писателя»)<br>Пояснения: обедня — церковная служба.`,
  key:'[ч\'н]: точного (1), точно (3, 4).<br>[шн]: конечно (1), скучно (3, 4).<br>[шт]: чтоб, что (4).<br>[ч\'т]: нечто (2), почту (5), мечта (6).'},
 {n:53,l:4,st:4,task:`Найти в каждом ряду лишнее слово по произношению чн или чт. Объяснить выбор.`,
  obr:``,
  body:`Ряды:<br>А) скворечник, Никитична, Саввична, сочно<br>Б) ночной, точный, яичница, речной<br>В) что, чтобы, нечто, что-нибудь<br>Г) почта, мачта, мечта, кое-что<br>Д) Ильинична, Никитична, Кузьминична, отличница<br>Е) конечный, бесконечный, конечно, вечный`,
  key:'А) сочно — [ч\'н], остальные с [шн] (скворечник — слово из списка, Никитична и Саввична — отчества). Б) яичница — [шн], остальные с [ч\'н]. В) нечто — [ч\'т], остальные с [шт]. Г) кое-что — [шт], остальные с [ч\'т]. Д) отличница — [ч\'н]: это не отчество, остальные — отчества на -ична с [шн]. Е) конечно — [шн], остальные с [ч\'н].'},
 {n:54,l:4,st:4,task:`Проверить транскрипцию слов. Определить слова, найти ошибки и исправить. Объяснить каждую ошибку.`,
  obr:``,
  body:`Записи:<br>А) [со́шный']<br>Б) [наро́ч'на]<br>В) [ма́шта]<br>Г) [уда́ч'ный']<br>Д) [н'ик'и́т'ишна]<br>Е) [паштал'й'о́н]<br>Ж) [ч'то́бы]<br>З) [атл'и́шна]<br>И) [м'ич'та́т']<br>К) [й'ии́ч'н'ица]`,
  key:'А) сочный — ошибка, [со́ч\'ный\']: слова нет в списке [шн]. Б) нарочно — ошибка, [наро́шна]: слово из списка. В) мачта — ошибка, [ма́ч\'та]: это не «что». Г) удачный — верно. Д) Никитична — верно. Е) почтальон — ошибка, [пач\'тал\'й\'о́н]: чт как пишется. Ж) чтобы — ошибка, [што́бы]. З) отлично — ошибка, [атл\'и́ч\'на]. И) мечтать — верно. К) яичница — ошибка, [й\'ии́шн\'ица].'},
 {n:55,l:4,st:4,task:`Сравнить, как написано отчество у Тургенева и у Брюсова. 1) Как произносится это отчество? 2) Почему Брюсов написал «Ильинишна»? 3) Как пишется отчество по правилам? 4) Найти в предложении 2 ещё одно слово с сочетанием чн и указать его произношение.`,
  obr:``,
  body:`Предложения:<br>1. Татьяна Ильинична потупилась, улыбнулась и покраснела. (И. С. Тургенев, «Записки охотника»)<br>2. Дарья Ильинишна мне глубоко симпатична… (В. Я. Брюсов, «Обручение Даши»)`,
  key:'1) [ил\'й\'и́н\'ишна] — с [шн].<br>2) Писатель передал на письме живое произношение: так это отчество и произносится по норме.<br>3) Ильинична — с буквами чн.<br>4) Симпатична — [ч\'н]: слово не из списка и не отчество.'},
 {n:56,l:4,st:2,task:`Словарный диктант. Записать под диктовку слова в два столбика: [ч'н] и [шн]. Проверить написание: во всех словах пишется чн.`,
  obr:`Вечно — в столбик [ч'н].`,
  body:`Слова для диктовки: вечно, Лукинична, срочный, Саввична, точно, Кузьминична, научный, отличный, дачник, Никитична, восточный, Фоминична, бесконечный.`,
  key:'[ч\'н]: вечно, срочный, точно, научный, отличный, дачник, восточный, бесконечный.<br>[шн]: Лукинична, Саввична, Кузьминична, Никитична, Фоминична (все — отчества на -ична).'},
 {n:57,l:4,st:4,task:`Записать транскрипцию слов. Отметить все трудные места: безударные гласные, сочетания чн и чт, непроизносимые согласные, оглушение.`,
  obr:``,
  body:`Почтальон, мечтательно, точно, столичный, Кузьминична, грустно, встречный, чтобы.`,
  key:'[пач\'тал\'й\'о́н] — о без ударения [а], чт как пишется, ьо — [й\'о]. [м\'ич\'та́т\'ил\'на] — е — [и], чт — [ч\'т], о на конце — [а]. [то́ч\'на] — чн — [ч\'н]. [стал\'и́ч\'ный\'] — о без ударения — [а], чн — [ч\'н]. [куз\'м\'и́н\'ишна] — чн — [шн]. [гру́сна] — т не произносится. [фстр\'э́ч\'ный\'] — в перед глухим — [ф], чн — [ч\'н]. [што́бы] — чт — [шт].'},
 {n:58,l:4,st:5,task:`Тонкость. Проверить по орфоэпическому словарю, как произносится чн в словах. Выписать слова, у которых два допустимых варианта, и слова с одним вариантом. Почему слова первой группы не берут в задания с одним ответом?`,
  obr:``,
  body:`Булочная, молочный, сливочный, порядочный, яблочный, гречневый, Саввична, вечный, ночной.`,
  key:'Два варианта ([ч\'н] и [шн]): булочная, молочный, сливочный, порядочный, яблочный, гречневый — в новейших словарях основным обычно указано [ч\'н], [шн] — старшая московская норма.<br>Один вариант: Саввична — только [шн]; вечный, ночной — только [ч\'н].<br>Если оба варианта верны, у задания нет единственного ответа.'},
 {n:59,l:6,st:5,os:'сочинение',task:`Написать сочинение-миниатюру (6–8 предложений) на тему «Почему мы говорим [кан'э́шна], а пишем «конечно»». Условия: 1) объяснить, откуда в произношении [шн]; 2) привести не меньше четырёх слов с [шн] и двух похожих слов с [ч'н]; 3) сравнить слова «что» и «нечто»; 4) сделать вывод о том, как связаны произношение и письмо.`,
  obr:``,body:``,
  key:'Критерии: объяснено, что [шн] — след старого московского произношения; есть 4 слова с [шн] (конечно, скучно, нарочно, яичница, скворечник, отчества на -ична) и 2 похожих с [ч\'н] (конечный, бесконечный, точно); сравнены «что» [шт] и «нечто» [ч\'т]; есть вывод (письмо сохраняет единый облик слова, а произношение следует норме); 6–8 предложений.<br>Образец: Когда-то в Москве почти все слова с чн произносили с [шн]. Со временем победило произношение по написанию, но несколько слов сохранили старую норму: конечно, скучно, нарочно, яичница. Похожие слова — конечный, бесконечный — уже звучат с [ч\'н]. Так же и с чт: мы говорим [што], но [н\'э́ч\'та]. Письмо при этом не меняется: оно сохраняет облик слова и связывает его с родственными словами. Поэтому говорить нужно по норме, а писать по правилам орфографии.'},
 {n:60,l:4,st:3,task:`Прочитать разговор по ролям. Выписать слова с сочетаниями чн и чт и указать их произношение. Найти два слова с непроизносимыми согласными (повторение урока 3).`,
  obr:`Чтобы — [шт].`,
  body:`— Ты что такой грустный?<br>— Скучно. Все ушли на каток, а я дома.<br>— Так пошли! Правда, лёд уже не тот, что утром, но кататься можно.<br>— Зовёшь, чтобы я опять упал?<br>— Нет, честно. А потом зайдём на почту: мама просила отправить посылку.<br>— Ладно. Только сначала яичницу доем.`,
  key:'Что (дважды) — [шт]; скучно — [шн]; чтобы — [шт]; почту — [ч\'т]; яичницу — [шн].<br>Непроизносимые согласные: грустный (т), честно (т). Кроме того: кататься — ться звучит как [ца].'},
// ── Урок 5. Заимствованные слова
 {n:61,l:5,st:1,task:`Распределить слова в два столбика: согласный перед е произносится твёрдо; согласный перед е произносится мягко. Проверить себя по орфоэпическому словарю.`,
  obr:`Шимпанзе — твёрдо ([зэ]); президент — мягко.`,
  body:`Кафе, музей, шоссе, термин, пюре, тема, кашне, пионер, ателье, шинель, полонез, фанера, кабаре, пакет, интервью, девиз.`,
  key:'Твёрдо: кафе, шоссе, пюре, кашне, ателье, полонез, кабаре, интервью.<br>Мягко: музей, термин, тема, пионер, шинель, фанера, пакет, девиз.'},
 {n:62,l:5,st:2,task:`Составить с каждым словом сочетание из двух-трёх слов и прочитать вслух. Подчеркнуть согласный, который перед е произносится твёрдо.`,
  obr:`Светлый интерьер — т перед е твёрдый.`,
  body:`Ателье, партер, тире, компьютер, теория, термин, бактерия, катер, коттедж, кортеж.`,
  key:'Например: ателье мод (т — твёрдо), места в партере (т — твёрдо), длинное тире (р — твёрдо), новый компьютер (т — твёрдо), интересная теория (мягко), научный термин (мягко), опасная бактерия (мягко), быстрый катер (мягко), загородный коттедж (т — твёрдо), свадебный кортеж (т — твёрдо).'},
 {n:63,l:5,st:2,task:`Записать транскрипцию слов. Объяснить, почему в словах с ш и ж перед ю нет мягкости, а в словах с ьо на месте о два звука.`,
  obr:`Брошюра — [брашу́ра]: ш всегда твёрдый, ю обозначает [у].`,
  body:`Парашют, жюри, бульон, шампиньон, почтальон, проект, медальон, павильон.`,
  key:'[парашу́т], [жур\'и́], [бул\'й\'о́н], [шамп\'ин\'й\'о́н], [пач\'тал\'й\'о́н], [праэ́кт], [м\'идал\'й\'о́н], [пав\'ил\'й\'о́н].<br>[ж] и [ш] всегда твёрдые, поэтому ю после них обозначает только [у]. Ь перед о — разделительный, поэтому о обозначает два звука [й\'о]. В слове «проект» после о звучит [э] без [й\'].'},
 {n:64,l:5,st:3,task:`Прочитать предложения вслух. Выписать заимствованные слова, в которых согласный перед е произносится твёрдо; для сравнения выписать заимствованные слова, где согласный перед е мягкий (имена не рассматривать). Найти ещё по одному слову на правила уроков 3 и 4: г в -ого, тс.`,
  obr:`Например: коттедж — твёрдо [тэ].`,
  body:`Предложения:<br>1. Литвинов пожал плечами и отправился к Веберу, взял газету и спросил себе мороженого. (И. С. Тургенев, «Дым»)<br>2. В вагонах я заметил даже нескольких мужиков, читавших газеты, большею частию вслух. (Ф. М. Достоевский, «Дневник писателя»)<br>3. А ведь какая интереснейшая тема и как раз в наше время! (Ф. М. Достоевский, «Дневник писателя»)<br>4. Откуда-то, с верхнего шоссе, доносился звонкий и дробный топот лошади, бежавшей иноходью. (А. И. Куприн, «Белый пудель»)<br>5. Тут он опять увидел белое кашне и бледное лицо. (А. П. Чехов, «Враги»)<br>6. Моя солдатская шинель — как печать отвержения. (М. Ю. Лермонтов, «Герой нашего времени»)<br>7. Я надел старую шинель и взял зонтик, потому что шёл проливной дождик. (Н. В. Гоголь, «Записки сумасшедшего»)<br>Пояснения: иноходь — бег лошади, при котором она переставляет одновременно обе ноги с одной стороны; печать отвержения — знак человека, которого отвергли.`,
  key:'Твёрдо: шоссе, кашне. Мягко (для сравнения): газету, газеты, интереснейшая, тема, шинель (6, 7).<br>Повторение: мороженого, верхнего — г звучит как [в]; солдатская — тс звучит как [ц].'},
 {n:65,l:5,st:3,task:`Прочитать текст. Выписать слова, в которых согласный перед е произносится твёрдо; для сравнения выписать слова, где согласный перед е мягкий. Найти в тексте ещё четыре слова с трудными местами из прошлых уроков и объяснить их произношение.`,
  obr:`Омлет — м перед е мягкий.`,
  body:`Я часто вспоминаю летнюю поездку в Москву. Сначала мы побывали в музее. Потом пообедали в маленьком кафе: я заказал пюре с котлетой, а сестра — омлет и компот. Вечером мы гуляли по набережной, а на следующий день отправились по шоссе за город. Там проходил фестиваль, и в огромном шатре пел хор. Было весело и интересно.`,
  key:'Твёрдо: кафе, пюре, шоссе. Мягко (для сравнения): музее, котлетой, омлет, фестиваль, сестра, вечером и др.<br>Прошлые уроки, например: часто — о на конце без ударения звучит как [а] ([ч\'а́ста]); весело — е и о без ударения ([в\'э́с\'ила]); шатре — а после ш без ударения — [а]; поездку — д перед глухим — [т].'},
 {n:66,l:5,st:4,task:`Найти в каждом ряду лишнее слово. Объяснить выбор.`,
  obr:``,
  body:`Ряды:<br>А) кабаре, купе, резюме, газета<br>Б) музей, тема, шоссе, термин<br>В) ателье, интервью, компьютер, пионер<br>Г) шинель, фанера, кашне, девиз<br>Д) брошюра, парашют, жюри, бюро<br>Е) кортеж, коттедж, партер, президент`,
  key:'А) газета — мягко, остальные твёрдо. Б) шоссе — твёрдо, остальные мягко. В) пионер — мягко, остальные твёрдо. Г) кашне — твёрдо, остальные мягко. Д) бюро — [б\'] мягкий перед ю, а в остальных ж и ш твёрдые и ю обозначает [у]. Е) президент — мягко, остальные твёрдо.'},
 {n:67,l:5,st:3,task:`Мини-исследование. Найти слова в орфоэпическом словаре и выписать помету о произношении согласного перед е. Какие согласные чаще всего произносятся твёрдо?`,
  obr:`Ателье́ [тэ].`,
  body:`Купе, тире, ателье, интервью, компьютер, шимпанзе, партер, кортеж, коттедж, фонетика, синтетика, цитадель, гантель.`,
  key:'Купе́ [пэ], тире́ [рэ], ателье́ [тэ], интервью́ [тэ], компью́тер [тэ], шимпанзе́ [зэ], парте́р [тэ], корте́ж [тэ], котте́дж [тэ], фоне́тика [нэ], синте́тика [тэ], цитаде́ль [дэ], ганте́ль [тэ].<br>Чаще всего твёрдыми бывают зубные согласные [т], [д], [н], [с], [з], а также [р].'},
 {n:68,l:5,st:2,task:`1) Сравнить произношение согласного перед э и перед е в парах. Записать транскрипцию слов. 2) Составить сочетания из двух-трёх слов с тремя словами на э. 3) Объяснить, почему в словах с буквой э не возникает вопроса, твёрдый ли согласный.`,
  obr:`Мэр [мэ́р] — мера [м'э́ра]: перед э — [м], перед е — [м'].`,
  body:`Сэр — серый; пэр — пена; мэтр — метро; мэрия — мерка; сэр — сера; пэр — перо. Пояснения: пэр — титул знатного человека в Англии; мэтр — признанный мастер, учитель.`,
  key:'1) [сэ́р] — [с\'э́рый\']; [пэ́р] — [п\'э́на]; [мэ́тр] — [м\'итро́]; [мэ́р\'ий\'а] — [м\'э́рка]; [сэ́р] — [с\'э́ра]; [пэ́р] — [п\'иро́].<br>2) Например: мэрия города, английский сэр, мэтр живописи.<br>3) Буква э после согласного всегда показывает, что согласный твёрдый. Трудность возникает только там, где пишется е, а звучит [э] после твёрдого: кафе, шоссе.'},
 {n:69,l:5,st:3,task:`Поставить ударение и указать, твёрдо или мягко произносится согласный перед е. Подчеркнуть слова с ударением на последнем слоге.`,
  obr:`Партер — твёрдо.`,
  body:`Интерьер, резюме, кабаре, полонез, цитадель, гантель, фонетика, синтетика, бактерия, брюнет, термометр, катер, ракета, планета, президент.`,
  key:'Интерье́р (тв.), резюме́ (р — мягк., м — тв.), кабаре́ (тв.), полоне́з (тв.), цитаде́ль (тв.), ганте́ль (тв.), фоне́тика (тв.), синте́тика (тв.), бакте́рия (мягк.), брюне́т (мягк.), термо́метр (мягк.), ка́тер (мягк.), раке́та (мягк.), плане́та (мягк.), президе́нт (мягк.).<br>Ударение на последнем слоге: интерье́р, резюме́, кабаре́, полоне́з, цитаде́ль, ганте́ль, брюне́т, президе́нт.'},
 {n:70,l:5,st:4,task:`Составить объявление (5–6 предложений) об открытии кафе в школе. Использовать не меньше шести слов из списка; подчеркнуть согласные, которые перед е произносятся твёрдо. Прочитать объявление вслух.`,
  obr:`Уютный интерьер — т перед е твёрдый.`,
  body:`Слова: кафе, пюре, интерьер, компьютер, фестиваль, конфета, газета, омлет, котлета.`,
  key:'Образец: Дорогие ребята! В понедельник в нашей школе открывается кафе. На завтрак — омлет, на обед — котлета с картофельным пюре, к чаю — конфеты. Уютный интерьер придумали ученики седьмого класса. Меню можно посмотреть на компьютере у входа. Подробности — в школьной газете.<br>Твёрдо: кафе, пюре, интерьер, компьютер. Мягко: фестиваль, конфета, газета, омлет, котлета.'},
 {n:71,l:5,st:4,task:`Экскурсовод произнёс слова так, как записано. Определить слова, найти ошибки и исправить. Отметить верные варианты.`,
  obr:``,
  body:`Записи:<br>А) [каф'э́]<br>Б) [муз'э́й']<br>В) [шас'э́]<br>Г) [т'э́рм'ин]<br>Д) [брашу́ра]<br>Е) [прай'э́кт]<br>Ж) [кашн'э́]<br>З) [т'э́ма]<br>И) [бул'о́н]<br>К) [п'иан'э́р]`,
  key:'А) кафе — ошибка, [кафэ́]. Б) музей — верно. В) шоссе — ошибка, [шасэ́]. Г) термин — верно. Д) брошюра — верно. Е) проект — ошибка, [праэ́кт]. Ж) кашне — ошибка, [кашнэ́]. З) тема — верно. И) бульон — ошибка, [бул\'й\'о́н]. К) пионер — верно.'},
 {n:72,l:5,st:3,task:`Записать транскрипцию слов. Подчеркнуть твёрдые согласные перед [э].`,
  obr:`Тире — [т'ирэ́].`,
  body:`Кабаре, резюме, шимпанзе, тире, синтетика, фонетика, фанера, конфета, пакет, комета, телефон.`,
  key:'[кабарэ́], [р\'из\'умэ́], [шымпанзэ́], [т\'ирэ́], [с\'интэ́т\'ика], [фанэ́т\'ика], [фан\'э́ра], [канф\'э́та], [пак\'э́т], [кам\'э́та], [т\'ил\'ифо́н].<br>Твёрдые перед [э]: кабаре, резюме, шимпанзе, тире, синтетика, фонетика. В остальных словах согласный перед е мягкий.'},
 {n:73,l:5,st:3,task:`Записать предложения под диктовку. Выписать заимствованные слова, в которых согласный перед е произносится твёрдо, и заимствованные слова, где он мягкий. Записать транскрипцию слов «шоссе», «кашне», «купе», «тему».`,
  obr:`Шоссе — твёрдо.`,
  body:`Предложения:<br>1. По обоим бокам шоссе притаился тёмный курчавый кустарник. (А. И. Куприн, «Белый пудель»)<br>2. Кашне белело только спереди, позади же оно пряталось за длинными волосами. (А. П. Чехов, «Враги»)<br>3. Газета может потерять репутацию. (Н. В. Гоголь, «Нос»)<br>4. Ну, извольте, сделаю вам удовольствие, переменю тему. (Ф. М. Достоевский, «Униженные и оскорблённые»)<br>5. Я сел в соседнем купе, — оно было пусто, — и до первой станции сидел тут и плакал. (А. П. Чехов, «О любви»)`,
  key:'Твёрдо: шоссе, кашне, купе. Мягко: газета, репутацию, тему.<br>[шасэ́], [кашнэ́], [купэ́], [т\'э́му].'},
 {n:74,l:5,st:5,task:`Тонкость. Сравнить пометы в разных словарях. В словаре Д. Э. Розенталя у слов из списка дано твёрдое произношение согласного перед е. Проверить эти слова по новейшему орфоэпическому словарю и выяснить, есть ли у них второй вариант. Почему эти слова не берут в задания с одним ответом?`,
  obr:``,
  body:`Тест [тэ], темп [тэ], термос [тэ], свитер [тэ], модель [дэ], теннис [тэ], тент [тэ].`,
  key:'В новейших словарях у многих из этих слов наряду с твёрдым допускается и мягкое произношение ([т\'э]ст, мо[д\'э]ль и т. п.) — слова «обрусевают» и постепенно смягчают согласный. Пока норма колеблется, правильными считаются оба варианта, поэтому у задания на такое слово не было бы одного ответа.'},
 {n:75,l:5,st:5,task:`Тонкость. По пособию Н. В. Адамчик, в некоторых заимствованных словах без ударения сохраняется ясный [о]. Проверить слова по орфоэпическому словарю и распределить: в словаре только [о]; допустимы [о] и [а]. Сделать вывод.`,
  obr:``,
  body:`Досье, боа, Шопен, Вольтер, отель, поэт, сонет, рояль.`,
  key:'По Н. В. Адамчик: [о] — досье, боа, Шопен, Вольтер, отель; [о] и [а] — сонет, рояль, поэт. В новейших словарях в обиходных словах (отель, поэт) всё чаще основным считается [а], а [о] — допустимым. Вывод: ясный безударный [о] — уходящая черта книжных и редких слов; такие слова проверяют по словарю и не берут в задания с одним ответом.'},
// ── Повторение
 {n:76,l:6,st:4,task:`Найти в каждом слове все места, где произношение расходится с написанием, и назвать правило. В одном слове расхождений нет — найти его.`,
  obr:`Сердцевина [с'ирцыв'и́на]: е после мягкого — [и]; д не произносится; е после ц — [ы].`,
  body:`Черёмуха, мостовая, шерстинка, праздничный, песчинка, умываться, заводской, отличник, мачта, кортеж, интерьер, легчайший.`,
  key:'Черёмуха — е после мягкого без ударения — [и]. Мостовая — оба о без ударения — [а]. Шерстинка — е после ш — [ы]. Праздничный — д не произносится. Песчинка — е после мягкого без ударения — [и]; сч — [щ\']. Умываться — ться — [ца]. Заводской — о без ударения — [а]; дс — [ц]. Отличник — о в начале слова — [а]. Мачта — расхождений нет: [ма́ч\'та]. Кортеж — о без ударения — [а]; т перед е твёрдый; ж на конце — [ш]. Интерьер — т перед е твёрдый. Легчайший — е без ударения — [и]; гч — [хч\']; и после ш — [ы].'},
 {n:77,l:6,st:5,os:'чтение вслух',task:`Задание для абитуриентов. Чтение вслух. Подготовиться к чтению текста вслух: 1) подчеркнуть слова, в которых легко ошибиться в произношении (безударные гласные, сочетания согласных, тся, г в -ого); 2) записать, как произносятся трудные места; 3) прочитать текст вслух выразительно, соблюдая нормы.`,
  obr:``,
  body:`Был прекрасный июльский день, один из тех дней, которые случаются только тогда, когда погода установилась надолго. С самого раннего утра небо ясно; утренняя заря не пылает пожаром: она разливается кротким румянцем. Солнце — не огнистое, не раскалённое, как во время знойной засухи, не тускло-багровое, как перед бурей, но светлое и приветно лучезарное — мирно всплывает под узкой и длинной тучкой, свежо просияет и погрузится в лиловый её туман. (И. С. Тургенев, «Бежин луг»)`,
  key:'Трудные места: случаются, разливается — тся звучит как [ца]; погрузится — [ца]; самого, раннего — г звучит как [в]; погода, надолго, пожаром, огнистое, во (время) — о без ударения — [а]; приветно, свежо — е без ударения — [и]; лучезарное — е после ч без ударения — [и]; солнце — л не произносится; всплывает — в перед глухим — [ф]; узкой — з перед глухим — [с]; её — [й\'ий\'о́]; июльский — [ий\'у́л\'ск\'ий\'].<br>В слове «установилась» конечное с может звучать и мягко, и твёрдо — оба варианта допустимы, при оценке чтения не учитываются.'},
 {n:78,l:6,st:4,task:`Выполнить фонетический разбор слов по плану Н. В. Адамчик (глава «Звуки и буквы», урок «Фонетический разбор»). Отдельно отметить, где произношение расходится с написанием.`,
  obr:``,
  body:`Слова для разбора: честный, лёгкий, часы, мужчина.`,
  key:'Честный — [ч\'э́сный\']; [ч\'э́-сный\'] — 2 слога, ударный 1-й.<br>ч — [ч\'] — согл., глух. непарн., мягк. непарн.;<br>е — [э] — гл., уд.;<br>с — [с] — согл., глух. парн., тв. парн.;<br>т — [—] — не произносится;<br>н — [н] — согл., сонорн., зв. непарн., тв. парн.;<br>ы — [ы] — гл., безуд.;<br>й — [й\'] — согл., сонорн., зв. непарн., мягк. непарн.<br>7 букв, 6 звуков: т не произносится.<br>Лёгкий — [л\'о́хк\'ий\']; [л\'о́-хк\'ий\'] — 2 слога, ударный 1-й.<br>л — [л\'] — согл., сонорн., зв. непарн., мягк. парн.;<br>ё — [о] — гл., уд.;<br>г — [х] — согл., глух. непарн., тв. парн.;<br>к — [к\'] — согл., глух. парн., мягк. парн.;<br>и — [и] — гл., безуд.;<br>й — [й\'] — согл., сонорн., зв. непарн., мягк. непарн.<br>6 букв, 6 звуков; на месте г звучит [х].<br>Часы — [ч\'исы́]; [ч\'и-сы́] — 2 слога, ударный 2-й.<br>ч — [ч\'] — согл., глух. непарн., мягк. непарн.;<br>а — [и] — гл., безуд.;<br>с — [с] — согл., глух. парн., тв. парн.;<br>ы — [ы] — гл., уд.<br>4 буквы, 4 звука; на месте а без ударения звучит [и].<br>Мужчина — [мущ\'и́на]; [му-щ\'и́-на] — 3 слога, ударный 2-й.<br>м — [м] — согл., сонорн., зв. непарн., тв. парн.;<br>у — [у] — гл., безуд.;<br>ж, ч — [щ\'] — согл., глух. непарн., мягк. непарн.;<br>и — [и] — гл., уд.;<br>н — [н] — согл., сонорн., зв. непарн., тв. парн.;<br>а — [а] — гл., безуд.<br>7 букв, 6 звуков: жч обозначают один звук [щ\'].'},
 {n:79,l:6,st:5,os:'диктант',task:`Записать текст под диктовку. Затем: 1) выписать слова с непроизносимыми согласными; 2) выписать слова, где чн или чт произносятся не так, как пишутся; 3) найти слово, в котором ться звучит как [ца]; 4) найти заимствованное слово с твёрдым согласным перед е; 5) записать транскрипцию слов «мягкий» и «чтобы».`,
  obr:``,
  body:`Здравствуй, зима! Сегодня ночью выпал первый снег. Мы сразу побежали во двор. Солнце светило ярко, и мягкий снег искрился. Мальчишки строили крепость, а девочки лепили снеговика. Скучно не было никому. Чтобы согреться, мы бегали наперегонки. Потом мама позвала нас домой: на столе уже стояли горячий чай и пюре с котлетами. Честное слово, такой счастливой субботы у нас давно не было!`,
  key:'1) Здравствуй (первая в), солнце (л), честное (т), счастливой (т).<br>2) Скучно — [шн]; чтобы — [шт].<br>3) Согреться.<br>4) Пюре — р перед е твёрдый.<br>5) [м\'а́хк\'ий\'], [што́бы].'},
 {n:80,l:6,st:3,task:`Вспомним: глава «Ударение», урок «Трудные слова. Орфоэпическая норма». Поставить ударение в словах. Подчеркнуть слова, в которых, кроме ударения, есть безударный гласный после щ или твёрдый согласный перед е, и назвать это трудное место.`,
  obr:`Резюме́ — м перед е твёрдый.`,
  body:`Щавель, звонит, торты, документ, каталог, резюме, квартал, портфель, красивее, шимпанзе, щеколда, жалюзи.`,
  key:'Щаве́ль, звони́т, то́рты, докуме́нт, катало́г, резюме́, кварта́л, портфе́ль, краси́вее, шимпанзе́, щеко́лда, жалюзи́.<br>Подчеркнуть: щаве́ль, щеко́лда — а и е после щ без ударения звучат как [и]: [щ\'ив\'э́л\'], [щ\'ико́лда]; резюме́, шимпанзе́ — согласный перед е твёрдый; в слове шимпанзе́ ещё и и после ш звучит как [ы].'},
 {n:81,l:6,st:3,task:`Повторение главы «Слог и перенос». Разделить слова на слоги, поставить ударение и записать транскрипцию, отделяя слоги чёрточкой, как в образце. Указать, сколько в слове безударных слогов.`,
  obr:`Дорога — [да-ро́-га]: 3 слога, безударных 2.`,
  body:`Сосулька, тропинка, жилет, учитель, весёлый, черёмуха, молодец, голубика.`,
  key:'[са-су́л\'-ка] — 3 слога, безударных 2. [тра-п\'и́н-ка] — 3, безударных 2. [жы-л\'э́т] — 2, безударный 1. [у-ч\'и́-т\'ил\'] — 3, безударных 2. [в\'и-с\'о́-лый\'] — 3, безударных 2. [ч\'и-р\'о́-му-ха] — 4, безударных 3. [ма-ла-д\'э́ц] — 3, безударных 2. [га-лу-б\'и́-ка] — 4, безударных 3.'},
 {n:82,l:6,st:4,task:`Иностранец, который учит русский язык, записал текст так, как слышал. Найти и исправить ошибки. Назвать правило произношения, из-за которого он ошибся.`,
  obr:`«Сиводня» — сегодня: г в этом слове звучит как [в], е без ударения — как [и].`,
  body:`«Сиводня утром сонце светило ярко. Мы с братом пашли в лес. Там было тиха и совсем не скушно. Мяхкий мох пружинил пад нагами. Брат сказал: „Штобы не заблудица, держись рядом“. Я был щастлив. Конешно, мы вирнулись дамой к обеду.»`,
  key:'Сегодня (г — [в], е — [и]); солнце (л не произносится); пошли (о — [а]); тихо (о на конце — [а]); скучно ([шн]); мягкий (гк — [хк]); под ногами (о — [а]); чтобы ([шт]); заблудиться (ться — [ца]); счастлив (сч — [щ\'], т не произносится); конечно ([шн]); вернулись (е — [и]); домой (о — [а]).'},
 {n:83,l:6,st:4,task:`Лингвистическая задача. Объяснить, почему слова каждой пары похожи на письме, но звучат по-разному в выделенном месте.`,
  obr:``,
  body:`Пары: что — нечто; конечно — конечный; поздно — поздравить; мягкий — много; пюре — перо; учится — чистит; синего — снега; сердце — сердечко.`,
  key:'Что [шт] — нечто [ч\'т]: [шт] только в «что» и словах от него. Конечно [шн] — конечный [ч\'н]: [шн] только в словах из списка. Поздно (д не звучит, здн) — поздравить (д звучит: здн нет). Мягкий (гк — [хк]) — много (г перед гласным — [г]). Пюре (р перед е твёрдый) — перо (р перед е мягкий). Учится (тся — [ца]) — чистит (т и с звучат отдельно, сочетания тся нет). Синего (г в -его — [в]) — снега (г — [г]). Сердце (д не звучит, рдц) — сердечко (д звучит).'},
 {n:84,l:6,st:4,task:`Прочитать стихи. 1) Записать транскрипцию слов «дорога», «пролегла», «сибирских», «песчаная». 2) Выписать слова, в которых безударные о и е звучат как [а] и [и]. 3) Найти слово, в котором две буквы обозначают один звук.`,
  obr:``,
  body:`Там в полях, за синей гущей лога, / В зелени озёр, / Пролегла песчаная дорога / До сибирских гор. (С. А. Есенин, «В том краю, где жёлтая крапива…») Пояснения: лог — широкий овраг.`,
  key:'1) [даро́га], [прал\'игла́], [с\'иб\'и́рск\'их], [п\'ищ\'а́най\'а].<br>2) [а]: полях (о), до (о), озёр (о), пролегла (о), дорога (первая о); [и]: зелени (вторая е), пролегла (е), песчаная (е). (Безударные окончания в словах синей, гущей не учитываются.)<br>3) Песчаная — сч обозначают один звук [щ\'].'},
 {n:85,l:6,st:5,os:'сочинение',task:`Написать сочинение (7–9 предложений) на тему «Правильная речь — уважение к собеседнику». Условия: 1) употребить не меньше шести слов из разных уроков главы (безударные гласные, непроизносимые согласные, тся/ться, чн или чт, заимствованное слово с твёрдым согласным перед е) и подчеркнуть трудное место; 2) записать транскрипцию трёх из них; 3) привести пример ошибки, которая встречается в речи окружающих, и объяснить, как произносить правильно.`,
  obr:``,body:``,
  key:'Критерии: тема раскрыта, есть рассуждение и вывод; не меньше шести слов из разных уроков с подчёркнутыми трудными местами (например: конечно — [шн], честный — т, учиться — [ца], что — [шт], кафе — [фэ], молоко — [а]); три верные транскрипции; приведён и объяснён пример ошибки; 7–9 предложений.'},
 {n:86,l:6,st:3,task:`Составить памятку для одноклассников «Десять слов, в которых легко ошибиться»: выбрать по два слова из каждого урока главы (уроки 2–5) и ещё два — на ударение; записать произношение трудного места и правило.`,
  obr:`Молоко — [малако́]: о без ударения звучит как [а].`,body:``,
  key:'Например: молоко — [малако́] (о без ударения — [а]); жена — [жына́] (е после ж — [ы]); честный — т не произносится; учиться — [уч\'и́ца]; конечно — [кан\'э́шна]; что — [што]; кафе — [кафэ́] (ф твёрдый); музей — [муз\'э́й\'] (з мягкий); звонит — звони́т; торты — то́рты. Принимаются любые верные примеры с правилом.'}
];
const PZ_LNAMES=['',...PZ.lessons.map(l=>l.t),'Повторение'];
const PZ_BOOKREF={1:'Адамчик, «Орфоэпия»: понятие об орфоэпии, история литературного произношения; Розенталь, «Русский язык» (пособие), приложение «Не ошибайтесь в ударениях!» (пометы произношения)',2:'Адамчик, «Орфоэпия»: характеристика современного произношения; Розенталь, «Русский язык» (пособие), § 5, п. 1, 3, 6–8',3:'Адамчик, «Орфоэпия»: характеристика современного произношения; Розенталь, «Русский язык» (пособие), § 5, п. 5–8',4:'Адамчик, «Орфоэпия» (чн, чт); Розенталь, «Русский язык» (пособие), приложение — слова с пометой [шн]',5:'Адамчик, «Орфоэпия» (иноязычные слова); Розенталь, «Русский язык» (пособие), § 5, п. 2, 4; упр. 19'};
